<?php require_once __DIR__.'/includes/functions.php';$token=$_GET['token']??'';$msg='Invalid or expired verification link.';if($token!==''){$hash=hash('sha256',$token);$s=$db->prepare('SELECT id,user_id FROM email_verifications WHERE token_hash=? AND used_at IS NULL AND expires_at>NOW()');$s->bind_param('s',$hash);$s->execute();$v=$s->get_result()->fetch_assoc();if($v){$db->begin_transaction();try{$s=$db->prepare('UPDATE users SET is_verified=1 WHERE id=?');$s->bind_param('i',$v['user_id']);$s->execute();$s=$db->prepare('UPDATE email_verifications SET used_at=NOW() WHERE id=?');$s->bind_param('i',$v['id']);$s->execute();$db->commit();$msg='Email verified successfully. You can now log in.';log_action('email_verified','users',$v['user_id']);}catch(Throwable $e){$db->rollback();$msg='Verification failed. Please request a new link.';}}}$title='Email verification';require 'includes/header.php';?><div class="panel"><h1>Email verification</h1><p><?=e($msg)?></p><a class="btn" href="<?=url('login.php')?>">Go to login</a></div><?php require 'includes/footer.php';?>
